# ⭐ Le fond des bandeaux est BLANC (sceau Maeva 28/09 : « blanchi là où il
#   y a le gris »). Sur sa planche ils sont gris clair, mesuré 211/255.
#   UNE SEULE VALEUR pour revenir en arrière.
_FOND_BANDEAU = None
_RENTRE_BANDEAU = 0.4 * mm

# ══ LA TAILLE DES CHIFFRES ═══════════════════════════════════════════
_T_CASE = 27.0
# ⚠️⚠️ CE N'EST PAS LE TRAIT QUI COMMANDE ICI, C'EST L'ŒIL — la leçon du
#    MOOREA : si le blanc ENTRE deux nombres n'est pas nettement plus
#    large que le blanc DANS un nombre, on lit « 1935 » au lieu de
#    « 19 » et « 35 ». Règle de la maison : au moins 2,5 fois.
#
# ⭐ 2e PLANCHE DU 28/09. Ses grilles sont passées de 474 à 489 pixels de
#    large et la rangée de 80 à 86 pixels de haut. MAIS LA HAUTEUR N'A
#    JAMAIS ÉTÉ LA CONTRAINTE : huit nombres à deux chiffres sur UNE
#    ligne, c'est la largeur qui décide. Le pas passe de 31,32 à
#    32,17 pt, soit 2,7 % — d'où UN point de chiffre en plus.
#    Mesuré, blanc contre blanc, sur cette planche :
#       26 pt -> 5,50 entre / 1,74 dedans = 3,16x   confortable
#       27 pt -> 4,47 entre / 1,79 dedans = 2,50x   ← INSTALLÉ, pile
#                                                     sur la règle
#       28 pt -> 3,44 entre / 1,81 dedans = 1,90x   ça se lit collé
#       29 pt -> 2,42 entre / 2,01 dedans = 1,20x   illisible
#    ⚠️ 27 pt est EXACTEMENT à la limite, sans marge. Si sur papier les
#      nombres se lisent collés, redescendre à 26 : une seule valeur.
#    ⚠️⚠️ POUR DES CHIFFRES NETTEMENT PLUS GROS il faut MOINS DE NOMBRES
#      PAR LIGNE — deux lignes de quatre, comme le 10 boules. Agrandir
#      la planche ne sert plus à rien : à 8 par ligne on est au bout.
_PLACES_REGULIERES = True   # False = revenir exactement sur ses pointillés


def _places(cols, pts):
    """Les huit abscisses où poser les nombres, en millièmes."""
    if not _PLACES_REGULIERES:
        return pts
    g0, bar, g1 = cols
    out = []
    for a, b in ((g0, bar), (bar, g1)):
        pas = (b - a) / 4.0
        out += [a + pas * (k + 0.5) for k in range(4)]
    return out


_T_SERIE = 5.5


def _poser_decor(c, x0, y0):
    """Grave la planche UNE FOIS par document, puis la tamponne.
    ⚠️ La marque est posée SUR LE CANEVAS, jamais dans un dictionnaire
    indexé par id() : Python réutilise les id() libérés et le deuxième
    document sortirait cassé."""
    nom = "OHANA8B18_DECOR"
    if not getattr(c, "_o818_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=FEUILLE_W, uppery=FEUILLE_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0
            n = len(contour)
            while i < n:
                cmd = contour[i]
                j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                else:
                    p.curveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H,
                              v[2] / 1000.0 * FEUILLE_W, FEUILLE_H - v[3] / 1000.0 * FEUILLE_H,
                              v[4] / 1000.0 * FEUILLE_W, FEUILLE_H - v[5] / 1000.0 * FEUILLE_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._o818_forme_faite = True
    c.saveState()
    c.translate(x0, y0)
    c.doForm(nom)
    c.restoreState()


def _gen_grille(rng):
    """Une grille : par plage, DEUX numéros différents, le petit d'abord.
    Les huit places, de gauche à droite : B B | I I ‖ G G | O O — les
    quatre premières à gauche de la barre, les quatre autres à droite."""
    vals = []
    for a, b in RANGES:
        x, y = sorted(rng.sample(range(a, b + 1), 2))
        vals.append(x)
        vals.append(y)
    return vals


# ⚠️⚠️ 28/09 — DEUX GRILLES IDENTIQUES DANS LA MEME RAME : LE VRAI RISQUE.
#    Ce jeu ne peut fabriquer que 121 550 625 grilles differentes. Dans une rame de
#    500 feuilles il y a 9 000 grilles : le calcul dit une chance sur 3 qu'une paire s'y trouve.
#    Deux cartons identiques dans une salle, c'est deux gagnants en meme
#    temps sur le meme tirage.
#    ⭐ REMEDE : on garde en memoire, PENDANT TOUT LE DOCUMENT, les grilles
#      deja sorties, et on retire au sort tant qu'on retombe sur une
#      ancienne. Le document ne peut plus contenir deux grilles pareilles,
#      quelle que soit sa taille. Cout : quelques tirages de plus, invisible.
def _tirer(rng, deja):
    for _ in range(200):
        g = _gen_grille(rng)
        cle = tuple(g)
        if cle not in deja:
            deja.add(cle)
            return g
    return g


def _dessiner_feuille(c, x0, y0, grilles, series, couleur_hex, titre_jeu="",
                      telephone="", style="eco"):
    police_ch, gris_ch = _style_chiffres(style)
    col = colors.HexColor(couleur_hex)

    if _FOND_BANDEAU is not None:
        c.setFillColor(_FOND_BANDEAU)
        for cols, bandeau, rangee, pts in GRILLES:
            bx = x0 + cols[0] / 1000.0 * FEUILLE_W + _RENTRE_BANDEAU
            bw = (cols[2] - cols[0]) / 1000.0 * FEUILLE_W - 2 * _RENTRE_BANDEAU
            by = y0 + FEUILLE_H - bandeau[1] / 1000.0 * FEUILLE_H
            bh = (bandeau[1] - bandeau[0]) / 1000.0 * FEUILLE_H - _RENTRE_BANDEAU
            c.rect(bx, by, bw, bh, stroke=0, fill=1)

    c.setFillColor(col)
    _poser_decor(c, x0, y0)

    def MX(v):
        return x0 + v / 1000.0 * FEUILLE_W

    def MY(v):
        return y0 + FEUILLE_H - v / 1000.0 * FEUILLE_H

    for gi, (cols, bandeau, rangee, pts) in enumerate(GRILLES):
        vals = grilles[gi]
        cy = MY((rangee[0] + rangee[1]) / 2.0) - _T_CASE * 0.34
        places = _places(cols, pts)
        for k, n in enumerate(vals):
            cx = MX(places[k])
            if _sec:
                _sec.chiffre_micro(c, n, cx, cy, _T_CASE, gris_ch, police_ch,
                                   epaisseur=_GRAS_TRAIT)
            else:
                c.setFillColor(gris_ch)
                c.setFont(police_ch, _T_CASE)
                c.drawCentredString(cx, cy, str(n))
        c.setFillColor(GRIS)
        c.setFont(POLICE, _T_SERIE)
        c.drawString(MX(cols[0]) + 1.2 * mm, MY(bandeau[1]) + 1.2 * mm,
                     "N° %06d" % series[gi])
        if telephone:
            c.drawRightString(MX(cols[2]) - 1.2 * mm, MY(bandeau[1]) + 1.2 * mm,
                              telephone[:22])
        if _sec:
            try:
                _sec.cadre_micro(c, MX(cols[0]), MY(rangee[1]),
                                 MX(cols[2]) - MX(cols[0]),
                                 MY(bandeau[0]) - MY(rangee[1]),
                                 series[gi], retrait=0.7 * mm)
            except Exception:
                pass


def generer_pdf(nb_cartes=18, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", page_start=1):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=landscape(A4), pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE

    rng = random.Random(963000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    _deja = set()      # ⚠️ le sac des grilles deja sorties dans CE document

    for _ in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 8)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 5.0 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 5.0 * mm, "%03d" % no_page)

        grilles = [_tirer(rng, _deja) for _ in range(CARTES_PAGE)]
        series = [serie + k for k in range(CARTES_PAGE)]
        coul = (couleur_perso if (couleur and couleur_perso)
                else RAINBOW[(serie - 1) % len(RAINBOW)] if couleur else "#555555")
        _dessiner_feuille(c, MARGE_X, MARGE_Y, grilles, series, coul,
                          titre_jeu, telephone, style=style)
        serie += CARTES_PAGE
        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
